  }
  if (seg.type === "scene") {
    return <SceneRenderer key={key} storyboard={seg.markdown} />;
  }
  if (seg.type === "question") {
    try {
      const form = normalizeQuestionForm(JSON.parse(JSON.parse(seg.json)));
      if (!form) return null;
