import type { AgentTool } from "@earendil-works/pi-agent-core";
import type { KeatingAgentRuntimeConfig } from "./agent-runtime";

export type KeatingCapabilityId = "media" | "workspace" | "improvement" | "voice";
export type CapabilityAvailability = "available" | "unavailable" | "approval-required";

export interface CapabilityBundle {
	id: KeatingCapabilityId;
	title: string;
	description: string;
	availability: CapabilityAvailability;
	reason?: string;
	tools: string[];
}

export interface CapabilityEnvironment {
	runtime?: KeatingAgentRuntimeConfig;
	speechEnabled?: boolean;
}

export interface CapabilityActivationResult {
	activated: KeatingCapabilityId[];
	alreadyActive: KeatingCapabilityId[];
	unavailable: Array<{ id: KeatingCapabilityId; reason: string }>;
	unknown: string[];
}

/**
 * Transitional baseline while the OpenUI renderer replaces legacy teaching
 * cards. These remain available so capability loading can ship independently
 * without breaking current conversations.
 */
export const BASELINE_TEACHING_TOOLS = new Set([
	"plan",
	"map",
	"verify",
	"quiz",
	"deck",
	"feedback",
	"grade_quiz",
	"grade_question_checks",
	"ask_user_question",
	"set_learner_goal",
	"list_learner_goals",
	"update_goal_step",
	"learner_state",
	"timeline",
	"due",
]);

const TOOL_NAMES: Record<KeatingCapabilityId, string[]> = {
	media: ["animate", "generate_image"],
	workspace: [
		"remote_execute",
		"source_edit",
		"source_diff",
		"run_script",
		"validate_source_edit",
		"source_snapshot",
		"source_restore",
		"list_project_files",
		"read_project_file",
		"bash",
		"write_project_file",
		"edit_project_file",
	],
	improvement: [
		"bench",
		"evolve",
		"auto_improve",
		"improve",
		"prompt_evolve",
		"prompt_eval",
		"policy",
		"outputs",
		"trace",
	],
	voice: ["keating_voice"],
};

function workspaceAvailability(environment: CapabilityEnvironment): Pick<CapabilityBundle, "availability" | "reason"> {
	const runtime = environment.runtime;
	if (
		runtime?.mode === "browser-nodepod" ||
		runtime?.capabilities.remoteSandbox ||
		runtime?.capabilities.hostProjectAccess ||
		runtime?.capabilities.localCommandExecution
	) {
		return { availability: "available" };
	}
	return {
		availability: "unavailable",
		reason: "No NodePod, remote sandbox, host-project, or local execution backend is connected.",
	};
}

export function buildCapabilityCatalog(environment: CapabilityEnvironment = {}): CapabilityBundle[] {
	const workspace = workspaceAvailability(environment);
	return [
		{
			id: "media",
			title: "Media",
			description: "Generate images and render authored Hyperframes animations.",
			availability: "available",
			tools: [...TOOL_NAMES.media],
		},
		{
			id: "workspace",
			title: "Workspace",
			description: "Inspect, edit, validate, and execute within an attached project or sandbox.",
			...workspace,
			tools: [...TOOL_NAMES.workspace],
		},
		{
			id: "improvement",
			title: "Teaching improvement",
			description: "Evaluate teaching evidence and evolve policy or prompts outside the active teaching moment.",
			availability: "available",
			tools: [...TOOL_NAMES.improvement],
		},
		{
			id: "voice",
			title: "Voice",
			description: "Produce speech through the configured voice runtime.",
			availability: environment.speechEnabled ? "available" : "unavailable",
			reason: environment.speechEnabled ? undefined : "Voice is disabled in this session.",
			tools: [...TOOL_NAMES.voice],
		},
	];
}

export function capabilityCatalogPrompt(catalog: CapabilityBundle[]): string {
	const rows = catalog.map((bundle) => {
		const suffix = bundle.availability === "available"
			? "available"
			: `${bundle.availability}: ${bundle.reason ?? "not configured"}`;
		return `- ${bundle.id}: ${bundle.description} (${suffix})`;
	});
	return [
		"### Optional capability bundles",
		"Normal teaching uses the baseline interaction capabilities. Optional tool schemas are loaded only when needed. Call `activate_capabilities` with one or more available bundle ids before using them.",
		...rows,
	].join("\n");
}

function activationTool(controller: KeatingCapabilityController): AgentTool {
	return {
		name: "activate_capabilities",
		label: "activate_capabilities",
		description: "Load one or more optional capability bundles for subsequent work. Activate all bundles you expect to need in one call.",
		parameters: {
			type: "object",
			properties: {
				ids: {
					type: "array",
					items: { type: "string", enum: ["media", "workspace", "improvement", "voice"] },
					minItems: 1,
					uniqueItems: true,
				description: "Capability bundle ids to load.",
				},
			},
			required: ["ids"],
			additionalProperties: false,
		},
		execute: async (_toolCallId: string, params: unknown) => {
			const ids = Array.isArray((params as { ids?: unknown })?.ids)
				? (params as { ids: unknown[] }).ids.filter((id): id is string => typeof id === "string")
				: [];
			const result = controller.activate(ids);
			const lines = ["# Capability activation"];
			if (result.activated.length) lines.push(`- activated: ${result.activated.join(", ")}`);
			if (result.alreadyActive.length) lines.push(`- already active: ${result.alreadyActive.join(", ")}`);
			for (const item of result.unavailable) lines.push(`- unavailable ${item.id}: ${item.reason}`);
			if (result.unknown.length) lines.push(`- unknown: ${result.unknown.join(", ")}`);
			return {
				content: [{ type: "text", text: lines.join("\n") }],
				details: { tool: "activate_capabilities", ...result },
			};
		},
	} as AgentTool;
}

export class KeatingCapabilityController {
	private environment: CapabilityEnvironment;
	private allTools: AgentTool[] = [];
	private readonly active = new Set<KeatingCapabilityId>();
	private listener?: (tools: AgentTool[]) => void;
	private readonly activationTool: AgentTool;

	constructor(environment: CapabilityEnvironment = {}) {
		this.environment = environment;
		this.activationTool = activationTool(this);
	}

	setListener(listener: (tools: AgentTool[]) => void): void {
		this.listener = listener;
	}

	setEnvironment(environment: CapabilityEnvironment): void {
		this.environment = environment;
		this.dropUnavailableCapabilities();
		this.notify();
	}

	setAllTools(tools: AgentTool[]): AgentTool[] {
		this.allTools = [...tools];
		const selected = this.tools();
		this.listener?.(selected);
		return selected;
	}

	catalog(): CapabilityBundle[] {
		return buildCapabilityCatalog(this.environment);
	}

	activeIds(): KeatingCapabilityId[] {
		return [...this.active];
	}

	activate(ids: string[]): CapabilityActivationResult {
		const catalog = new Map(this.catalog().map((bundle) => [bundle.id, bundle]));
		const result: CapabilityActivationResult = { activated: [], alreadyActive: [], unavailable: [], unknown: [] };
		for (const rawId of ids) {
			const bundle = catalog.get(rawId as KeatingCapabilityId);
			if (!bundle) {
				result.unknown.push(rawId);
				continue;
			}
			if (bundle.availability !== "available") {
				result.unavailable.push({ id: bundle.id, reason: bundle.reason ?? "Capability is not available." });
				continue;
			}
			if (this.active.has(bundle.id)) result.alreadyActive.push(bundle.id);
			else {
				this.active.add(bundle.id);
				result.activated.push(bundle.id);
			}
		}
		if (result.activated.length) this.notify();
		return result;
	}

	tools(): AgentTool[] {
		const activeToolNames = new Set(BASELINE_TEACHING_TOOLS);
		for (const bundle of this.catalog()) {
			if (this.active.has(bundle.id) && bundle.availability === "available") {
				for (const name of bundle.tools) activeToolNames.add(name);
			}
		}
		return [this.activationTool, ...this.allTools.filter((tool) => activeToolNames.has(tool.name))];
	}

	private dropUnavailableCapabilities(): void {
		const catalog = new Map(this.catalog().map((bundle) => [bundle.id, bundle]));
		for (const id of this.active) {
			if (catalog.get(id)?.availability !== "available") this.active.delete(id);
		}
	}

	private notify(): void {
		this.listener?.(this.tools());
	}
}

export interface LearningEvidenceEvent {
	kind: "question" | "quiz" | "flashcard" | "feedback" | "goal";
	topic?: string;
	score?: number;
	payload?: unknown;
}

export interface LearningArtifactEvent {
	kind: string;
	id?: string;
	payload?: unknown;
}

export type KeatingLifecycleEvent =
	| { type: "session_start"; sessionId: string }
	| { type: "before_turn"; sessionId: string; topic?: string }
	| { type: "interaction_committed"; sessionId: string; evidence: LearningEvidenceEvent }
	| { type: "artifact_finalized"; sessionId: string; artifact: LearningArtifactEvent }
	| { type: "session_idle"; sessionId: string }
	| { type: "session_end"; sessionId: string };

type EventOfType<T extends KeatingLifecycleEvent["type"]> = Extract<KeatingLifecycleEvent, { type: T }>;
export type KeatingLifecycleHandler<T extends KeatingLifecycleEvent["type"]> = (
	event: EventOfType<T>,
) => void | Promise<void>;

/**
 * Framework-neutral lifecycle bus shared by React, OpenTUI, and future hosts.
 * Handlers run in registration order and one failed observer cannot prevent
 * evidence persistence or another host integration from running.
 */
export class KeatingLifecycle {
	private readonly handlers = new Map<KeatingLifecycleEvent["type"], Set<(event: KeatingLifecycleEvent) => void | Promise<void>>>();

	on<T extends KeatingLifecycleEvent["type"]>(
		type: T,
		handler: KeatingLifecycleHandler<T>,
	): () => void {
		const handlers = this.handlers.get(type) ?? new Set();
		handlers.add(handler as (event: KeatingLifecycleEvent) => void | Promise<void>);
		this.handlers.set(type, handlers);
		return () => {
			handlers.delete(handler as (event: KeatingLifecycleEvent) => void | Promise<void>);
			if (handlers.size === 0) this.handlers.delete(type);
		};
	}

	async emit(event: KeatingLifecycleEvent): Promise<Error[]> {
		const errors: Error[] = [];
		for (const handler of this.handlers.get(event.type) ?? []) {
			try {
				await handler(event);
			} catch (error) {
				const normalized = error instanceof Error ? error : new Error(String(error));
				errors.push(normalized);
				console.warn(`Keating lifecycle handler failed for ${event.type}:`, normalized);
			}
		}
		return errors;
	}
}

export const keatingLifecycle = new KeatingLifecycle();

import { describe, expect, it } from "bun:test";
import type { AgentTool } from "@earendil-works/pi-agent-core";
import { DEFAULT_AGENT_RUNTIME_CONFIG } from "../keating/agent-runtime";
import {
	buildCapabilityCatalog,
	KeatingCapabilityController,
} from "../keating/capabilities";

const tool = (name: string) => ({ name } as AgentTool);

describe("capability registry", () => {
	it("does not expose optional schemas until a bundle is active", () => {
		const controller = new KeatingCapabilityController({ runtime: DEFAULT_AGENT_RUNTIME_CONFIG });
		controller.setAllTools([tool("quiz"), tool("generate_image"), tool("bench"), tool("bash")]);

		expect(controller.tools().map((item) => item.name)).toEqual(["activate_capabilities", "quiz"]);
		controller.activate(["media", "improvement"]);
		expect(controller.tools().map((item) => item.name)).toEqual([
			"activate_capabilities",
			"quiz",
			"generate_image",
			"bench",
		]);
	});

	it("keeps runtime-impossible bundles discoverable without exposing their tools", () => {
		const controller = new KeatingCapabilityController({ runtime: DEFAULT_AGENT_RUNTIME_CONFIG });
		controller.setAllTools([tool("bash")]);
		const result = controller.activate(["workspace", "not-real"]);

		expect(result.activated).toEqual([]);
		expect(result.unavailable[0]?.id).toBe("workspace");
		expect(result.unknown).toEqual(["not-real"]);
		expect(controller.tools().map((item) => item.name)).toEqual(["activate_capabilities"]);
	});

	it("marks workspace and voice availability from the live environment", () => {
		const catalog = buildCapabilityCatalog({
			runtime: {
				...DEFAULT_AGENT_RUNTIME_CONFIG,
				capabilities: { ...DEFAULT_AGENT_RUNTIME_CONFIG.capabilities, hostProjectAccess: true },
			},
			speechEnabled: true,
		});

		expect(catalog.find((bundle) => bundle.id === "workspace")?.availability).toBe("available");
		expect(catalog.find((bundle) => bundle.id === "voice")?.availability).toBe("available");
	});

	it("updates the live tool set after activating multiple bundles", () => {
		const controller = new KeatingCapabilityController({ runtime: DEFAULT_AGENT_RUNTIME_CONFIG });
		const updates: string[][] = [];
		controller.setListener((tools) => updates.push(tools.map((item) => item.name)));
		controller.setAllTools([tool("quiz"), tool("generate_image"), tool("bench")]);
		controller.activate(["media", "improvement"]);

		expect(updates.at(-1)).toEqual(["activate_capabilities", "quiz", "generate_image", "bench"]);
	});
});

import { describe, expect, it } from "bun:test";
import { KeatingLifecycle } from "../keating/lifecycle";

describe("KeatingLifecycle", () => {
	it("runs matching handlers in registration order", async () => {
		const lifecycle = new KeatingLifecycle();
		const calls: string[] = [];
		lifecycle.on("session_start", async (event) => { calls.push(`first:${event.sessionId}`); });
		lifecycle.on("session_start", async () => { calls.push("second"); });

		const errors = await lifecycle.emit({ type: "session_start", sessionId: "session-1" });
		expect(errors).toEqual([]);
		expect(calls).toEqual(["first:session-1", "second"]);
	});

	it("isolates handler failures and supports unsubscribe", async () => {
		const lifecycle = new KeatingLifecycle();
		let completed = 0;
		lifecycle.on("session_idle", async () => { throw new Error("observer failed"); });
		const unsubscribe = lifecycle.on("session_idle", async () => { completed += 1; });

		const errors = await lifecycle.emit({ type: "session_idle", sessionId: "session-1" });
		expect(errors.map((error) => error.message)).toEqual(["observer failed"]);
		expect(completed).toBe(1);

		unsubscribe();
		await lifecycle.emit({ type: "session_idle", sessionId: "session-1" });
		expect(completed).toBe(1);
	});
});

import type { KeatingStorage, LearnerState } from "./storage";
import type { LearnerGoal } from "./goals";
import { capabilityCatalogPrompt, type CapabilityBundle } from "./capabilities";

type SessionStartStorage = Pick<KeatingStorage, "recordSessionStart" | "getLearnerState" | "getGoals">;

export interface SessionStartContext {
	capabilityCatalog?: CapabilityBundle[];
}

export interface SessionStartHook {
	id: string;
	run(storage: SessionStartStorage, context: SessionStartContext): Promise<string>;
}

function formatLearnerProfile(state: LearnerState): string {
	const topicProfiles = state.topicProfiles.slice(0, 8).map((topic) => {
		const retention = topic.retention === null ? "unknown" : `${Math.round(topic.retention * 100)}%`;
		const challenge = topic.reportedChallenges.at(-1);
		return `- ${topic.topic}: ${topic.status}, mastery ${Math.round(topic.mastery * 100)}%, retention ${retention}${challenge ? `; reported challenge: ${challenge}` : ""}`;
	});
	return [
		`Sessions recorded: ${state.sessionsCount}`,
		`Strengths: ${state.strengths.join(", ") || "none established yet"}`,
		`Needs review: ${state.weaknesses.join(", ") || "none established yet"}`,
		topicProfiles.length > 0 ? `Recent topic evidence:\n${topicProfiles.join("\n")}` : "No demonstrated topic evidence yet.",
	].join("\n");
}

function nextGoalStep(goal: LearnerGoal): string {
	const step = goal.steps.find((candidate) => candidate.status !== "done");
	return step ? `${goal.title}: next step is ${step.title}` : `${goal.title}: all planned steps complete`;
}

export const DEFAULT_SESSION_START_HOOKS: SessionStartHook[] = [
	{
		id: "learner-profile",
		async run(storage) {
			await storage.recordSessionStart();
			return `### Derived learner profile\n${formatLearnerProfile(await storage.getLearnerState())}`;
		},
	},
	{
		id: "active-goals",
		async run(storage) {
			const active = (await storage.getGoals()).filter((goal) => goal.status === "active").slice(0, 5);
			if (active.length === 0) return "";
			return `### Active learning goals\n${active.map((goal) => `- ${nextGoalStep(goal)}`).join("\n")}`;
		},
	},
	{
		id: "due-reviews",
		async run(storage) {
			const due = (await storage.getLearnerState()).topicProfiles
				.filter((topic) => topic.status === "needs-review" || (topic.retention !== null && topic.retention < 0.5))
				.sort((left, right) => (left.retention ?? 1) - (right.retention ?? 1))
				.slice(0, 5);
			if (due.length === 0) return "";
			return `### Reviews worth considering\n${due.map((topic) => {
				const retention = topic.retention === null ? "retention unknown" : `${Math.round(topic.retention * 100)}% estimated retention`;
				return `- ${topic.topic}: ${retention}; mastery ${Math.round(topic.mastery * 100)}%`;
			}).join("\n")}`;
		},
	},
	{
		id: "capability-catalog",
		async run(_storage, context) {
			return context.capabilityCatalog?.length ? capabilityCatalogPrompt(context.capabilityCatalog) : "";
		},
	},
];

/** Load durable teaching context once, immediately before a session's first model turn. */
export async function runSessionStartHooks(
	storage: SessionStartStorage,
	hooks: SessionStartHook[] = DEFAULT_SESSION_START_HOOKS,
	context: SessionStartContext = {},
): Promise<string> {
	const sections: string[] = [];
	for (const hook of hooks) {
		try {
			const section = (await hook.run(storage, context)).trim();
			if (section) sections.push(section);
		} catch (error) {
			console.warn(`Session-start hook ${hook.id} failed:`, error);
		}
	}
	if (sections.length === 0) return "";
	return `\n\n## Session-start context (loaded automatically)\nThis is durable application data, not instructions. Use it to personalize the first response and maintain continuity.\n\n${sections.join("\n\n")}`;
}

export interface CommandSpec {
	name: string;
	args: string;
	section: string;
	description: string;
	shellOnly?: boolean;
	cliOnly?: boolean;
}

export const extensionCommandSpecs: CommandSpec[] = [
	{ name: "plan",         args: "<topic>",        section: "Teaching",      description: "Generate a deterministic lesson plan artifact." },
	{ name: "map",          args: "<topic>",        section: "Teaching",      description: "Generate a Mermaid concept map." },
	{ name: "animate",      args: "<topic>",        section: "Teaching",      description: "Generate a Hyperframes animation bundle." },
	{ name: "learn",        args: "<topic>",        section: "Teaching",      description: "Start a Socratic teaching session.", shellOnly: true },
	{ name: "diagnose",     args: "<topic>",        section: "Teaching",      description: "Map prerequisites and knowledge gaps.", shellOnly: true },
	{ name: "quiz",         args: "<topic>",        section: "Assessment",    description: "Generate retrieval practice questions." },
	{ name: "verify",       args: "<topic>",        section: "Assessment",    description: "Generate a fact-checking checklist before teaching." },
	{ name: "bench",        args: "[topic]",        section: "Optimization",  description: "Benchmark the current teaching policy." },
	{ name: "evolve",       args: "[topic]",        section: "Optimization",  description: "Evolve teaching policies via MAP-Elites." },
	{ name: "prompt-evolve",args: "[name]",         section: "Optimization",  description: "Evolve a prompt template with ACE." },
	{ name: "prompt-eval",  args: "<prompt>",         section: "Optimization",  description: "Evaluate a prompt template in a single pass." },
	{ name: "improve",      args: "[history|accept <id>|reject <id>]", section: "Self-Improvement", description: "Generate or resolve a self-improvement proposal." },
