export function KeatingOpenUIRenderer({
	program,
	metadata,
	isStreaming = false,
}: {
	program: string;
	metadata: OpenUIDocumentMetadata;
	isStreaming?: boolean;
}) {
	const hostAction = useContext(OpenUIActionContext);
	const [errors, setErrors] = useState<OpenUIError[]>([]);
	const storage = useMemo(browserStorage, []);
	const initialState = useMemo(
		() => loadOpenUIState(storage, metadata),
		[storage, metadata.id, metadata.lifecycle],
	);

	const handleAction = useCallback(
		(event: ActionEvent) => {
			const action: KeatingOpenUIAction = {
				type: event.type,
				humanFriendlyMessage: event.humanFriendlyMessage,
				params: event.params,
				formState: event.formState,
				formName: event.formName,
				document: metadata,
			};
			hostAction?.(action);
			dispatchDocumentEvent("keating:openui-action", action as unknown as Record<string, unknown>);
		},
		[hostAction, metadata],
	);

	const handleStateUpdate = useCallback(
		(state: Record<string, unknown>) => {
			const persisted = saveOpenUIState(storage, metadata, state);
			dispatchDocumentEvent("keating:openui-state-updated", {
				document: metadata,
				state,
				persisted,
			});
		},
		[storage, metadata],
	);

	return (
		<div data-openui-document={metadata.id} data-openui-lifecycle={metadata.lifecycle}>
			{isStreaming ? (
				<div className={css({ marginBottom: "0.375rem", display: "flex", alignItems: "center", gap: "0.375rem", fontSize: "0.6875rem", color: "var(--muted-foreground)" })} role="status">
					<Loader2 aria-hidden="true" size={12} className={css({ animation: "spin 1s linear infinite", "@media (prefers-reduced-motion: reduce)": { animation: "none" } })} />
					Building interaction
				</div>
			) : null}
			<Renderer
				response={program}
				library={keatingOpenUILibrary}
				isStreaming={isStreaming}
				initialState={initialState}
				onAction={handleAction}
				onStateUpdate={handleStateUpdate}
				onError={setErrors}
			/>
			{!isStreaming && errors.length > 0 ? (
				<div className={css({ marginBlock: "0.75rem", display: "flex", alignItems: "flex-start", gap: "0.5rem", borderRadius: "0.5rem", background: "color-mix(in srgb, var(--destructive) 10%, transparent)", padding: "0.75rem", fontSize: "0.75rem", color: "var(--destructive)" })} role="alert">
					<CircleAlert aria-hidden="true" size={15} className={css({ marginTop: "0.0625rem", flexShrink: 0 })} />
					<span>This interaction could not be rendered completely. The surrounding lesson is still available.</span>
				</div>
			) : null}
		</div>
	);
}


import type {
	OpenUIDocumentMetadata,
	OpenUIInteractionLifecycle,
	OpenUIMessageSegment,
} from "./types";

const OPENUI_FENCE = /```openui(?:-lang)?(?:[ \t]+([^\n]*))?\n/g;
const CLOSE_FENCE = /\n```(?:\n|$)/g;
const DOCUMENT_ID = /^[a-zA-Z0-9][a-zA-Z0-9._:-]{0,127}$/;

function hashProgram(program: string): string {
	let hash = 2166136261;
	for (let index = 0; index < program.length; index += 1) {
		hash ^= program.charCodeAt(index);
		hash = Math.imul(hash, 16777619);
	}
	return (hash >>> 0).toString(36);
}

function parseLifecycle(value: string | undefined): OpenUIInteractionLifecycle {
	if (value === "resumable" || value === "workspace") return value;
	return "ephemeral";
}

function parseMetadata(header: string | undefined, program: string): OpenUIDocumentMetadata {
	const entries = new Map<string, string>();
	for (const token of header?.trim().split(/\s+/) ?? []) {
		const separator = token.indexOf("=");
		if (separator <= 0) continue;
		entries.set(token.slice(0, separator), token.slice(separator + 1));
	}
	const candidateId = entries.get("id");
	return {
		id: candidateId && DOCUMENT_ID.test(candidateId)
			? candidateId
			: `openui-${hashProgram(program.slice(0, 512))}`,
		lifecycle: parseLifecycle(entries.get("lifecycle")),
	};
}

/**
 * Split assistant text into Markdown and OpenUI programs.
 *
 * An opening fence is enough to produce an OpenUI segment, so the renderer can
 * consume the program while the assistant is still streaming it. Existing
 * Markdown and legacy `<keating-*>` tags remain untouched in text segments.
 */
export function parseOpenUIMessageSegments(text: string): OpenUIMessageSegment[] {
	const segments: OpenUIMessageSegment[] = [];
	let cursor = 0;
	OPENUI_FENCE.lastIndex = 0;
	let match: RegExpExecArray | null;

	while ((match = OPENUI_FENCE.exec(text)) !== null) {
		if (match.index > cursor) {
			segments.push({ type: "text", content: text.slice(cursor, match.index) });
		}

		const bodyStart = OPENUI_FENCE.lastIndex;
		CLOSE_FENCE.lastIndex = bodyStart;
		const closing = CLOSE_FENCE.exec(text);
		const bodyEnd = closing?.index ?? text.length;
		const program = text.slice(bodyStart, bodyEnd);
		segments.push({
			type: "openui",
			program,
			complete: closing !== null,
			metadata: parseMetadata(match[1], program),
		});

		if (!closing) {
			cursor = text.length;
			break;
		}
		cursor = CLOSE_FENCE.lastIndex;
		OPENUI_FENCE.lastIndex = cursor;
	}

	if (cursor < text.length) segments.push({ type: "text", content: text.slice(cursor) });
	if (segments.length === 0) segments.push({ type: "text", content: text });
	return segments;
}

/** Remove OpenUI source from text copied from an assistant message. */
export function stripOpenUIPrograms(text: string): string {
	return parseOpenUIMessageSegments(text)
		.filter((segment): segment is Extract<OpenUIMessageSegment, { type: "text" }> => segment.type === "text")
		.map((segment) => segment.content)
		.join("")
		.trim();
}

export const __test_parseOpenUIMetadata = parseMetadata;

/** How long an OpenUI learning document should remain available. */
export type OpenUIInteractionLifecycle = "ephemeral" | "resumable" | "workspace";

/** Metadata carried by an `openui` fenced block. */
export interface OpenUIDocumentMetadata {
	id: string;
	lifecycle: OpenUIInteractionLifecycle;
}

export type OpenUIMessageSegment =
	| { type: "text"; content: string }
	| {
			type: "openui";
			program: string;
			complete: boolean;
			metadata: OpenUIDocumentMetadata;
	  };

/** A host-level action emitted by an OpenUI learning component. */
export interface KeatingOpenUIAction {
	type: string;
	humanFriendlyMessage: string;
	params: Record<string, unknown>;
	formState?: Record<string, unknown>;
	formName?: string;
	document: OpenUIDocumentMetadata;
}


