function parsePolicyFromStorage(policy: Policy | null): TeacherPolicy {
	if (!policy) return DEFAULT_POLICY;

	const parsed = parsePolicyContent(policy.content);
	return clampPolicy({
		...DEFAULT_POLICY,
		...parsed,
		name: policy.id,
	});
}

function parsePolicyContent(content: string): Partial<TeacherPolicy> {
	const jsonBlock = content.match(/```json\s*([\s\S]*?)```/i)?.[1] ?? content;
	try {
		const parsed = JSON.parse(jsonBlock) as Partial<TeacherPolicy>;
		return typeof parsed === "object" && parsed !== null ? parsed : {};
	} catch {
		const parsed: Partial<Record<keyof Omit<TeacherPolicy, "name">, number>> = {};
		for (const field of POLICY_FIELDS) {
			const match = content.match(new RegExp(`${field}\\s*:\\s*(-?\\d+(?:\\.\\d+)?)`, "i"));
			if (match) {
				parsed[field] = Number(match[1]);
			}
		}
		return parsed;
	}
}

function policyToMarkdown(policy: TeacherPolicy, score: number): string {
	return [
		"# Evolved Teaching Policy",
		"",
		`Generated: ${new Date().toISOString()}`,
		`Score: ${score.toFixed(2)}/100`,
		"",
		"## Parameters",
		...POLICY_FIELDS.map((field) => `- ${field}: ${policy[field].toFixed(field === "exerciseCount" ? 0 : 3)}`),
		"",
		"```json",
		JSON.stringify(policy, null, 2),
		"```",
	].join("\n");
}

// Helper function to create tools with proper schema
function createTool(
	name: string,
	description: string,
	parameters: Record<string, unknown>,
	execute: (params: Record<string, unknown>) => Promise<string>,
	required?: string[],
): AgentTool {
	return {
		name,
		label: name,
		description,
		parameters: {
			type: "object",
			properties: parameters,
			...(required?.length ? { required } : {}),
			additionalProperties: false,
		},
		execute: async (_toolCallId: string, params: Record<string, unknown>) => {
			const result = await execute(params as Record<string, unknown>);
			return {
				content: [{ type: "text", text: result }],
				details: { tool: name },
			};
		},
	} as unknown as AgentTool;
}

async function executeToolText(
	tools: AgentTool[],
	name: string,
	params: Record<string, unknown>,
): Promise<string> {
	const tool = tools.find((candidate) => candidate.name === name);
	if (!tool) return `Capability unavailable: ${name} is not connected in this runtime.`;
	const result = await (tool.execute as any)(`keating-composed-${name}`, params, undefined, () => {});
	const content = (result as { content?: Array<{ type?: string; text?: string }> })?.content;
	return Array.isArray(content)
		? content.filter((item) => item?.type === "text" && typeof item.text === "string").map((item) => item.text).join("\n")
		: String(result ?? "");
}

type ResolvedTopic = ReturnType<typeof resolveTopic>;

function escapeHtml(value: string): string {
	return value
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;")
		.replace(/'/g, "&#39;");
}

interface StoryboardScene {
	number: number;
	title: string;
	duration: string;
	visual: string;
	audio?: string;
	transition?: string;
	highlight?: string;
}

/** Extract agent-authored scenes from a storyboard markdown document. */
export function parseStoryboardScenes(markdown: string): StoryboardScene[] {
	const lines = markdown.split(/\r?\n/);
	const scenes: StoryboardScene[] = [];
	let current: Partial<StoryboardScene> = {};
	for (const line of lines) {
		const titleMatch = line.match(/^#\s+Animation Storyboard:\s*(.+)$/);
		if (titleMatch) continue;
		const sceneMatch = line.match(/^##\s+Scene\s+(\d+):\s*(.+?)\s*\((\d+(?:\.\d+)?(?:\s*-\s*\d+(?:\.\d+)?)?s)\)\s*$/);
		if (sceneMatch) {
			if (current.title) scenes.push(current as StoryboardScene);
			current = {
				number: Number(sceneMatch[1]),
				title: sceneMatch[2].trim(),
				duration: sceneMatch[3].trim(),
			};
			continue;
		}
		const visualMatch = line.match(/^-\s*\*\*Visual\*\*:\s*(.+)$/);
		if (visualMatch) current.visual = visualMatch[1].trim();
		const audioMatch = line.match(/^-\s*\*\*(?:Audio|Narration)\*\*:\s*(.+)$/);
		if (audioMatch) current.audio = audioMatch[1].trim();
		const transMatch = line.match(/^-\s*\*\*Transition\*\*:\s*(.+)$/);
		if (transMatch) current.transition = transMatch[1].trim();
		const durMatch = line.match(/^-\s*\*\*Duration\*\*:\s*(\d+)s\s*$/);
		if (durMatch) current.duration = `${durMatch[1]}s`;
		const highlightMatch = line.match(/^-\s*\*\*(?:Highlight|Overlay|Step-through)\*\*:\s*(.+)$/);
		if (highlightMatch) current.highlight = highlightMatch[1].trim();
	}
	if (current.title) scenes.push(current as StoryboardScene);
	return scenes;
}

function parseStoryboardDurationSeconds(label: string): number {
	const cleaned = label.trim().replace(/s$/i, "");
	const range = cleaned.match(/^(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)$/);
	if (range) return Math.max(0.5, Number(range[2]) - Number(range[1]));
	const value = Number(cleaned);
	return Number.isFinite(value) ? Math.max(0.5, value) : 4;
}

function storyboardTitle(markdown: string): string {
	const match = markdown.match(/^#\s+Animation Storyboard:\s*(.+)$/m);
	return match ? match[1].trim() : "";
}

function buildAuthoredAnimationStoryboard(resolved: ResolvedTopic, summary: string): string {
	const premise = summary || resolved.summary;
	return [
		`# Animation Storyboard: ${resolved.title}`,
		"",
		"## Scene 1: Establish the question (0-3s)",
		`- **Visual**: Open with the core structure of ${resolved.title} and make the learner's starting question visible.`,
		`- **Narration**: ${premise}`,
		"- **Highlight**: Name the thing that will change on screen.",
		"",
		"## Scene 2: Show the motion (3-8s)",
		"- **Visual**: Use the authored Hyperframes scene to animate the central relationship, not just a static title card.",
		"- **Narration**: Point to the moving parts and connect them to the learner's intuition.",
		"- **Highlight**: The animation source is stored in the scene field.",
		"",
		"## Scene 3: Lock the takeaway (8-12s)",
		"- **Visual**: End on the key contrast, equation, or diagram state that should remain in memory.",
		"- **Narration**: State the transfer rule the learner can reuse.",
		"- **Transition**: Fade out after the final state is legible.",
		"",
	].join("\n");
}

function buildHyperframesComposition(resolved: ResolvedTopic, storyboard: string): string {
	// Use the agent-authored storyboard so every visible label, body line, and
	// duration reflects actual teaching content — not a generic template.
	const title = storyboardTitle(storyboard) || resolved.title;
	const scenes = parseStoryboardScenes(storyboard);
	const compositionId = `${resolved.slug}-lesson`;

	const clips =
		scenes.length > 0
			? scenes.map((scene, index) => {
				const start = scenes.slice(0, index).reduce((sum, prev) => sum + parseStoryboardDurationSeconds(prev.duration), 0);
				const duration = parseStoryboardDurationSeconds(scene.duration);
				return {
					start,
					duration,
					label: `Scene ${scene.number}`,
					title: scene.title,
					body: scene.visual || scene.highlight || scene.audio || scene.transition || "",
				};
			})
			: [{ start: 0, duration: 6, label: "Lesson", title: resolved.title, body: resolved.summary }];

	const encodedClips = JSON.stringify(clips.map((clip) => ({ selector: `#clip-${clip.start}`, start: clip.start })));

	return `<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <style>
    html, body { margin: 0; width: 100%; height: 100%; background: #0a0a0a; color: #f4f1e8; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; }
    #root { position: relative; width: 1920px; height: 1080px; overflow: hidden; background: linear-gradient(135deg, #0b0b0b 0%, #161616 55%, #211706 100%); }
    .clip { position: absolute; inset: 96px; display: grid; align-content: center; gap: 28px; opacity: 0; }
    .label { color: #f59e0b; font-size: 34px; letter-spacing: .16em; text-transform: uppercase; }
    h1, h2 { margin: 0; max-width: 1380px; font-size: 112px; line-height: 1; letter-spacing: 0; }
    p { margin: 0; max-width: 1220px; color: #d6d3ca; font-size: 48px; line-height: 1.24; }
    .rule { width: 420px; height: 8px; background: #f59e0b; }
  </style>
</head>
<body>
  <div id="root" data-composition-id="${escapeHtml(compositionId)}" data-start="0" data-width="1920" data-height="1080">
${clips.map((clip, index) => `    <section id="clip-${clip.start}" class="clip" data-start="${clip.start}" data-duration="${clip.duration}" data-track-index="${index}">
      <div class="label">${escapeHtml(clip.label)}</div>
      <${index === 0 ? "h1" : "h2"}>${escapeHtml(clip.title)}</${index === 0 ? "h1" : "h2"}>
      <div class="rule"></div>
      <p>${escapeHtml(clip.body)}</p>
    </section>`).join("\n")}
  </div>
  <script src="https://cdn.jsdelivr.net/npm/gsap@3/dist/gsap.min.js"></script>
  <script>
    const tl = gsap.timeline({ paused: true });
    const clips = ${encodedClips};
    for (const clip of clips) {
      tl.to(clip.selector, { opacity: 1, y: 0, duration: 0.45, ease: "power2.out" }, clip.start);
      tl.to(clip.selector, { opacity: 0, y: -28, duration: 0.35, ease: "power2.in" }, clip.start + 1.65);
    }
    window.__timelines = window.__timelines || {};
    window.__timelines[${JSON.stringify(compositionId)}] = tl;
    tl.play(0);
  </script>
</body>
</html>`;
}

function asStringArray(value: unknown, fallback: string[] = []): string[] {
	if (!Array.isArray(value)) return fallback;
	return value
		.map((entry) => String(entry ?? "").trim())
		.filter(Boolean)
		.slice(0, 6);
}

async function generateImageViaEndpoint(params: {
	endpoint: string;
	apiKey?: string;
	prompt: string;
	model: string;
	size: string;
	quality: string;
}): Promise<{ dataUrl: string; mimeType: string }> {
	const proxied = proxiedProviderRequestUrl(params.endpoint);
	const headers: Record<string, string> = {
		accept: "application/json",
		"content-type": "application/json",
		"x-target-url": proxied.targetBaseUrl,
	};
	if (params.apiKey) headers.Authorization = `Bearer ${params.apiKey}`;

	const response = await fetch(proxied.url, {
		method: "POST",
		headers,
		body: JSON.stringify({
			model: params.model,
			prompt: params.prompt,
			size: params.size,
			quality: params.quality,
			n: 1,
		}),
	});

	const payload = await response.json().catch(async () => ({ error: { message: await response.text().catch(() => response.statusText) } }));
	if (!response.ok) {
		const message = payload?.error?.message ?? response.statusText;
		throw new Error(`Image generation failed (${response.status}): ${String(message).slice(0, 500)}`);
	}

	const b64 = payload?.data?.[0]?.b64_json;
	if (!b64 || typeof b64 !== "string") {
		throw new Error("Image generation returned no base64 image data.");
	}

	return { dataUrl: `data:image/png;base64,${b64}`, mimeType: "image/png" };
}

function unavailableRemoteRuntimeMessage(runtime: KeatingAgentRuntimeConfig | undefined): string {
	if (!runtime || runtime.mode === "browser-only" || !runtime.executionEndpoint) {
		return [
			"# Remote Execution Unavailable",
			"",
			"Keating is running in browser-only mode. Run supported work in the browser and surface this fallback for operations that require native binaries, durable background compute, secure server-side secrets, public inbound networking, Docker/microVM isolation, or unrestricted host filesystem access.",
		].join("\n");
	}

	return "";
}

function stringifyRemoteResult(value: unknown): string {
	const text = typeof value === "string" ? value : JSON.stringify(value, null, 2);
	if (text.length <= 12000) return text;
	return `${text.slice(0, 12000)}\n\n[remote output truncated]`;
}

export interface KeatingToolsOptions {
	agentRuntime?: KeatingAgentRuntimeConfig;
	speech?: {
		settings: WebSpeechSettings;
		getApiKey: (provider: string) => Promise<string | undefined>;
	};
	setSystemPrompt?: (basePrompt: string) => void;
	/** Loads stored chat sessions so benchmarks can mine real transcripts and attribute signals to the model that taught them. */
	getSessionSamples?: () => Promise<BenchSessionSample[]>;
}

export async function createKeatingTools(
	storage: KeatingStorage,
	options: KeatingToolsOptions = {}
): Promise<AgentTool[]> {
	// All real learner evidence in one place: explicit feedback, signals inferred
	// from stored session transcripts, and graded quiz results — each attributed
	// to the model that was teaching where possible.
	const collectRealOutcomes = async (): Promise<BrowserLearnerOutcome[]> => {
		const learnerState = await storage.getLearnerState();
		const samples = options.getSessionSamples
			? await options.getSessionSamples().catch(() => [] as BenchSessionSample[])
			: [];
		const modelBySessionId = new Map(
			samples.filter((sample) => sample.id).map((sample) => [sample.id, benchModelLabel(sample.model)])
		);
		const quizRecords = await storage.getQuizResults().catch(() => []);
		return [
			...extractBrowserOutcomes(learnerState.feedbackHistory, learnerState.topicsExplored),
			...extractSessionTurnOutcomes(samples),
			...quizRecordsToOutcomes(quizRecords, modelBySessionId),
		];
	};

	const tools: AgentTool[] = [
		// agent_runtime - Inspect current agent execution mode and fallback policy
		createTool(
			"agent_runtime",
			"Inspect current agent execution mode, available sandbox capabilities, and fallback policy. Use before attempting source execution, native tooling, secret-backed work, or remote-only operations.",
			{},
			async () => {
				const runtime = options.agentRuntime;
				if (!runtime) {
					return "Agent runtime config is unavailable. Assume browser-only local execution and surface clear fallback errors for remote-only work.";
				}

				const capabilities = Object.entries(runtime.capabilities)
					.map(([key, value]) => `- ${key}: ${String(value)}`)
					.join("\n");
				const remote = runtime.remote
					? [
						"",
						"## Remote Sandbox",
						`- provider: ${runtime.remote.provider}`,
						`- endpoint: ${runtime.remote.endpoint ?? "local server default"}`,
						`- region: ${runtime.remote.region ?? "default"}`,
						`- snapshot: ${runtime.remote.snapshot ?? "default"}`,
						`- cpu: ${runtime.remote.cpu ?? "default"}`,
						`- memory: ${runtime.remote.memory ?? "default"}`,
						`- disk: ${runtime.remote.disk ?? "default"}`,
					].join("\n")
					: "";

				const nodePodActive = isNodePodActive();
				const nodePod = nodePodActive
					? [
						"",
						"## NodePod Sandbox",
						`- active: true`,
						`- local endpoint: ${NODEPOD_LOCAL_ENDPOINT}`,
						`- operations: shell.exec, fs.read, fs.write, snapshot.create`,
					].join("\n")
					: "";

				return [
					`# Agent Runtime`,
					"",
					`- mode: ${runtime.mode}`,
					`- label: ${runtime.label}`,
					`- execution endpoint: ${runtime.executionEndpoint ?? "none"}`,
					`- cloud endpoint: ${runtime.cloudEndpoint ?? "none"}`,
					`- project root: ${runtime.projectRoot ?? "none"}`,
					`- project files endpoint: ${runtime.projectFilesEndpoint ?? "none"}`,
					"",
					"## Capabilities",
					capabilities,
					remote,
					nodePod,
					"",
					"## Fallback Policy",
					`- local first: ${runtime.fallback.localFirst}`,
					`- remote available: ${runtime.fallback.remoteAvailable}`,
					`- message: ${runtime.fallback.message}`,
				].join("\n");
			}
		),

		// remote_execute - Send remote-only work to the configured microVM/cloud runtime
		createTool(
			"remote_execute",
			"Execute remote-only agent work through the configured microVM or Keating Cloud backend. Use only when browser-local tools cannot satisfy the request.",
			{
				operation: {
					type: "string",
					description: "Remote operation name, such as shell.exec, fs.read, fs.write, snapshot.create, or sandbox.provision",
				},
				payload: {
					type: "object",
					description: "Operation-specific JSON payload. For shell.exec, use { command, args, cwd, env, timeoutMs }.",
					additionalProperties: true,
				},
			},
			async (params) => {
				const runtime = options.agentRuntime;

					{
						path: { type: "string", description: "Relative path from the project root." },
						search: { type: "string", description: "Exact text to find. Must be unique in the file." },
						replace: { type: "string", description: "Replacement text." },
					},
					async (params) => {
						const relPath = typeof params.path === "string" ? params.path.replace(/^\/+/, "") : "";
						if (!relPath) return "Error: path is required.";
						const search = typeof params.search === "string" ? params.search : "";
						const replace = typeof params.replace === "string" ? params.replace : "";
						if (!search) return "Error: search is required.";
						try {
							const readRes = await fetch(`${projectFilesEndpoint}/${relPath}`, { headers: { accept: "application/json" } });
							if (!readRes.ok) {
								const text = await readRes.text().catch(() => "");
								return `# Edit Failed\n\n- status: ${readRes.status}\n- error: ${text || readRes.statusText}`;
							}
							const file = (await readRes.json()) as { content: string };
							const occurrences = file.content.split(search).length - 1;
							if (occurrences === 0) return `# Edit Failed\n\nSearch block not found in ${relPath}.`;
							if (occurrences > 1) return `# Edit Failed\n\nSearch block appears ${occurrences} times in ${relPath}; add more surrounding context to make it unique.`;
							const updated = file.content.replace(search, replace);
							const writeRes = await fetch(`${localExecEndpoint}/write`, {
								method: "POST",
								headers: { accept: "application/json", "content-type": "application/json" },
								body: JSON.stringify({ path: relPath, content: updated }),
							});
							if (!writeRes.ok) {
								const text = await writeRes.text().catch(() => "");
								return `# Edit Failed\n\n- status: ${writeRes.status}\n- error: ${text || writeRes.statusText}`;
							}
							const data = (await writeRes.json()) as { path: string; bytes: number };
							return `# Edited ${data.path}\n\n(${data.bytes} bytes)`;
						} catch (e) {
							return `# Edit Failed\n\n${e instanceof Error ? e.message : String(e)}`;
						}
					},
					["path", "search", "replace"],
				),
			);
		}
	}

	// Consolidated capability surfaces. The legacy tools above remain as
	// internal adapters during migration, but are not advertised by the
	// capability registry once these composed operations are available.
	tools.push(
		createTool(
			"evaluate_teaching",
			"Evaluate current teaching evidence or a prompt without changing policy. Use this to test a concrete hypothesis before requesting improvement.",
			{
				kind: { type: "string", enum: ["evidence", "prompt"], description: "Evaluate learner evidence with the benchmark, or evaluate supplied prompt content." },
				topic: { type: "string", description: "Optional topic scope for evidence evaluation." },
				prompt: { type: "string", description: "Prompt content, required when kind is prompt." },
				hypothesis: { type: "string", description: "The teaching hypothesis this evaluation is intended to test." },
			},
			async (params) => {
				const kind = params.kind === "prompt" ? "prompt" : "evidence";
				const hypothesis = String(params.hypothesis ?? "").trim();
				const result = kind === "prompt"
					? await executeToolText(tools, "prompt_eval", { prompt: params.prompt })
					: await executeToolText(tools, "bench", { topic: params.topic });
				return [hypothesis ? `# Evaluation hypothesis\n\n${hypothesis}` : "", result].filter(Boolean).join("\n\n");
			},
			["kind"],
		),
		createTool(
			"request_teaching_improvement",
			"Direct a safeguarded teaching-improvement run after the active teaching moment. State the evidence-backed hypothesis and whether policy, prompt, or both should change.",
			{
				scope: { type: "string", enum: ["policy", "prompt", "both"], description: "Which teaching surface may change." },
				hypothesis: { type: "string", description: "Required, falsifiable explanation of what should improve and why." },
				topic: { type: "string", description: "Optional topic scope." },
				target_objectives: { type: "array", items: { type: "string" }, description: "Optional evaluation objectives to emphasize in the report." },
			},
			async (params) => {
				const scope = ["policy", "prompt", "both"].includes(String(params.scope)) ? String(params.scope) : "both";
				const hypothesis = String(params.hypothesis ?? "").trim();
				if (!hypothesis) return "A concrete improvement hypothesis is required.";
				const targetObjectives = Array.isArray(params.target_objectives)
					? params.target_objectives.filter((value): value is string => typeof value === "string")
					: [];
				const result = scope === "policy"
					? await executeToolText(tools, "evolve", { topic: params.topic })
					: scope === "prompt"
						? await executeToolText(tools, "prompt_evolve", { name: "learn" })
						: await executeToolText(tools, "auto_improve", { topic: params.topic });
				return [
					"# Directed teaching improvement",
					`- scope: ${scope}`,
					`- hypothesis: ${hypothesis}`,
					targetObjectives.length ? `- target objectives: ${targetObjectives.join(", ")}` : "",
					"",
					result,
				].filter((line) => line !== "").join("\n");
			},
			["scope", "hypothesis"],
		),
		createTool(
			"workspace_inspect",
			"Batch read-only workspace operations. Use one call for related directory listings, file reads, and sandbox diffs.",
			{
				requests: {
					type: "array",
					minItems: 1,
					items: {
						type: "object",
						properties: {
							operation: { type: "string", enum: ["list", "read", "diff"] },
							path: { type: "string" },
						},
						required: ["operation"],
					},
				},
			},
			async (params) => {
				const requests = Array.isArray(params.requests) ? params.requests : [];
				const sections: string[] = [];
				for (const request of requests) {
					if (!request || typeof request !== "object") continue;
					const item = request as Record<string, unknown>;
					const operation = String(item.operation ?? "");
					const toolName = operation === "list" ? "list_project_files" : operation === "read" ? "read_project_file" : operation === "diff" ? "source_diff" : "";
					if (!toolName) continue;
					sections.push(await executeToolText(tools, toolName, { path: item.path }));
				}
				return sections.join("\n\n---\n\n") || "No valid inspection requests were supplied.";
			},
			["requests"],
		),
		createTool(
			"workspace_exec",
			"Execute one or more commands through the connected local, NodePod, or remote backend. Commands are run sequentially and stop after the first failure.",
			{
				commands: {
					type: "array",
					minItems: 1,
					items: {
						type: "object",
						properties: {
							command: { type: "string" },
							args: { type: "array", items: { type: "string" } },
							cwd: { type: "string" },
							timeout_ms: { type: "number" },
						},
						required: ["command"],
					},
				},
			},
			async (params) => {
				const commands = Array.isArray(params.commands) ? params.commands : [];
				const sections: string[] = [];
				for (const command of commands) {
					if (!command || typeof command !== "object") continue;
					const item = command as Record<string, unknown>;
					const commandName = String(item.command ?? "").trim();
					if (!commandName) continue;
					const args = Array.isArray(item.args) ? item.args.map(String) : [];
					const localTool = tools.some((tool) => tool.name === "bash");
					const output = localTool
						? await executeToolText(tools, "bash", { command: commandName, args, cwd: item.cwd, timeoutMs: item.timeout_ms })
						: await executeToolText(tools, "remote_execute", {
							operation: "shell.exec",
							payload: { command: commandName, args, cwd: item.cwd, timeoutMs: item.timeout_ms },
						});
					sections.push(output);
					if (/failed|exit code:\s*[1-9]/i.test(output)) break;
				}
				return sections.join("\n\n---\n\n") || "No valid commands were supplied.";
			},
			["commands"],
		),
		createTool(
			"workspace_change",
			"Apply one or more precise edits through the connected workspace adapter. NodePod edits may include validation and automatic rollback.",
			{
				edits: {
					type: "array",
					minItems: 1,
					items: {
						type: "object",
						properties: {
							path: { type: "string" },
							search: { type: "string" },
							replace: { type: "string" },
							reason: { type: "string" },
							test_script: { type: "string" },
						},
						required: ["path", "search", "replace"],
					},
				},
			},
			async (params) => {
				const edits = Array.isArray(params.edits) ? params.edits : [];
				const sections: string[] = [];
				for (const edit of edits) {
					if (!edit || typeof edit !== "object") continue;
					const item = edit as Record<string, unknown>;
					const path = String(item.path ?? "");
					const nodePod = isNodePodActive();
					const output = await executeToolText(tools, nodePod ? "source_edit" : "edit_project_file", nodePod
						? { file: path, search: item.search, replace: item.replace, reason: item.reason }
						: { path, search: item.search, replace: item.replace });
					sections.push(output);
					if (/edit failed|capability unavailable/i.test(output)) break;
					if (nodePod && typeof item.test_script === "string" && item.test_script.trim()) {
						const validation = await executeToolText(tools, "validate_source_edit", {
							file: path,
							testScript: item.test_script,
							autoRollback: true,
						});
						sections.push(validation);
						if (/FAILED/.test(validation)) break;
					}
				}
				return sections.join("\n\n---\n\n") || "No valid edits were supplied.";
			},
			["edits"],
		),
	);

	if (options.speech?.settings.enabled) {
		tools.push(createSpeechTool(options.speech.settings, options.speech.getApiKey));
	}

	return tools;
}


function slugifyDeckTitle(value: string): string {
	return value
		.toLowerCase()
		.trim()
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-+|-+$/g, "")
		.slice(0, 80);
}

function draftDeckCardId(deckSlug: string, index: number): string {
	if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
		return `${deckSlug}-${crypto.randomUUID()}`;
	}
	return `${deckSlug}-${Date.now()}-${index + 1}`;
}
