function preserveRegistrationOrder(groups: AgentTool[][]): AgentTool[] {
	const tools = groups.flat();
	const byName = new Map(tools.map((tool) => [tool.name, tool]));
	const ordered = TOOL_REGISTRATION_ORDER.flatMap((name) => {
