function extractVersion(title: string): string | undefined {
  const m = title.match(/v(\d+\.\d+\.\d+)/);
  return m ? m[1] : undefined;
}

function majorMinor(version: string): string {
  return version.split(".").slice(0, 2).join(".");
}

